effect.shader:
void main() {
    float colsF = max(float(int(columns + 0.5)), 1.0);
    float rowsF = max(float(int(rows + 0.5)), 1.0);
    vec2 grade = vec2(colsF, rowsF);

    // O pixel vira "coordenada de célula + fração dentro dela".
    vec2 escalado = acScreenNorm * grade;
    vec2 celula = floor(escalado);
    vec2 dentro = fract(escalado);

    // O `gap` encolhe o UV útil da célula; o resto vira transparente (margem).
    float margem = clamp(gap * 0.5, -0.4, 0.4);
    vec2 util = (dentro - margem) / max(1.0 - 2.0 * margem, 1e-4);
    if (any(lessThan(util, vec2(0.0))) || any(greaterThan(util, vec2(1.0)))) {
        fragColor = vec4(0.0);
        return;
    }

    // Reescala em volta do meio da célula para `cellScale`.
    vec2 uvNaCamada = (util - 0.5) / max(cellScale, 1e-4) + 0.5;
    if (any(lessThan(uvNaCamada, vec2(0.0))) || any(greaterThan(uvNaCamada, vec2(1.0)))) {
        fragColor = vec4(0.0);
        return;
    }

    // Defasagem: cada célula puxa um instante diferente do conteúdo (preview estático
    // ignora `acTime`, mas na timeline isso dá a onda clássica de grade animada).
    // Aqui só altera a opacidade pelo tempo, já que o conteúdo é UMA textura.
    float d = (celula.x + celula.y * colsF) / max(colsF * rowsF, 1.0);
    float fasador = 0.5 + 0.5 * cos(6.2831853 * (acTime / max(phase, 1e-3) - d));
    float opacidadeDaFase = phase > 1e-3 ? mix(0.4, 1.0, fasador) : 1.0;

    // Esmaecer do centro para o canto: índice normalizado da célula.
    vec2 centroCelula = (celula + 0.5) / grade - 0.5;
    float distanciaAoCentro = length(centroCelula) / 0.7071;
    float opacidadeDoFade = mix(1.0, 1.0 - clamp(distanciaAoCentro, 0.0, 1.0), fade);

    vec4 c = texture(inputImg, uvNaCamada);
    c *= opacidadeDaFase * opacidadeDoFade;

    fragColor = c;
}
